-- Phase 4 legal: archive the exact legal texts that consent hashes refer to, and hash
-- consent-row IP / device metadata with a dedicated consent_meta_pepper (not
-- private.encryption_keys and not the trainer-code pepper).
--
--  * public.legal_text_versions is append-only (kind, version, sha256, full_text,
--    first_shown_at). Seeded from the bundled texts at deploy / by the following
--    migration (generated by scripts/seed-legal-text-versions.mjs). Kept at least as
--    long as the longest consent-record retention: without the archived text, the
--    hash proves nothing.
--  * Consent metadata hashing uses private.consent_meta_hash:
--      1. Preferred: SET LOCAL app.consent_meta_pepper and app.consent_meta_pepper_version
--         in the transaction that writes the consent (edge secret or KMS HMAC). The
--         edge helper is supabase/functions/_shared/consentMeta.ts.
--      2. Dev fallback only: private.consent_meta_dev_pepper (clearly labeled; never
--         stored in private.encryption_keys).
--      3. If no pepper is available: leave ip_hash / device_hash null, record
--         meta_pepper_version as null, and raise a consent_meta_pepper_missing audit
--         event that contains the user id only — never an IP.
--  * Each consent_events row stores meta_pepper_version next to the hashes.
--  * Hashes have the same retention as consent records (account life + 4 years;
--    minors at least until their 22nd birthday) and are kept on deletion under the
--    legal-claims exemption. They are personal data (TDPSA); never describe them as
--    de-identified.
--  * private.client_ip() may only feed hashing. Never write a raw IP to a table,
--    log, or analytics event.
--
-- TODO(export): public.request_data_export() only queues a pending row; the packer is
-- not built. When it is, the access-request pack must include, for each of the
-- requester's consent_events: kind, granted, at, versions, text_hash, policy_doc_hash,
-- subject_user_id, actor_user_id, ip_hash, device_hash, app_version, meta_pepper_version,
-- and the matching legal_text_versions rows (kind, version, sha256, full_text,
-- first_shown_at). Never include a raw IP.

-- ------------------------------------------------------------------ legal_text_versions
create table public.legal_text_versions (
  id              uuid primary key default gen_random_uuid(),
  kind            text not null,
  version         text not null,
  sha256          text not null check (sha256 ~ '^[0-9a-f]{64}$'),
  full_text       text not null,
  first_shown_at  timestamptz not null default now(),
  unique (kind, version),
  unique (kind, sha256)
);

comment on table public.legal_text_versions is
  'Append-only archive of the exact legal text that a consent hash refers to. Seeded from bundled texts; keep at least as long as consent records.';

alter table public.legal_text_versions enable row level security;
alter table public.legal_text_versions force row level security;
revoke all on table public.legal_text_versions from public, anon, authenticated;
grant select on public.legal_text_versions to authenticated;
grant select, insert on public.legal_text_versions to service_role;

create policy legal_text_versions_read on public.legal_text_versions
  for select to authenticated
  using (true);

create or replace function private.legal_text_versions_append_only()
returns trigger
language plpgsql
as $$
begin
  raise exception 'legal_text_versions_append_only';
end;
$$;

drop trigger if exists legal_text_versions_no_update on public.legal_text_versions;
create trigger legal_text_versions_no_update
  before update or delete on public.legal_text_versions
  for each row execute function private.legal_text_versions_append_only();

revoke all on function private.legal_text_versions_append_only() from public, anon, authenticated;

create or replace function private.put_legal_text_version(
  p_kind text, p_version text, p_sha256 text, p_full_text text
)
returns void
language plpgsql
security definer
set search_path = public, extensions, pg_temp
as $$
declare
  v_kind text := btrim(p_kind);
  v_ver  text := btrim(p_version);
  v_hash text := lower(btrim(p_sha256));
  v_exist public.legal_text_versions%rowtype;
  v_digest text;
begin
  if v_kind is null or v_kind = '' or v_ver is null or v_ver = '' or p_full_text is null then
    raise exception 'legal_text_version_required';
  end if;
  if v_hash is null or v_hash !~ '^[0-9a-f]{64}$' then
    raise exception 'legal_text_version_hash';
  end if;
  v_digest := encode(extensions.digest(convert_to(p_full_text, 'UTF8'), 'sha256'), 'hex');
  if v_digest <> v_hash then
    raise exception 'legal_text_version_hash_mismatch';
  end if;
  select * into v_exist from public.legal_text_versions where kind = v_kind and version = v_ver;
  if found then
    if v_exist.sha256 <> v_hash or v_exist.full_text <> p_full_text then
      raise exception 'legal_text_version_immutable';
    end if;
    return;
  end if;
  insert into public.legal_text_versions (kind, version, sha256, full_text)
  values (v_kind, v_ver, v_hash, p_full_text);
end;
$$;

revoke all on function private.put_legal_text_version(text, text, text, text) from public, anon, authenticated;

insert into public.retention_policies (record_type, keep_rule, implemented, status) values
  ('legal_text_versions',
   'At least as long as the longest consent-record retention (account life + 4 years; minors at least until their 22nd birthday). The archived text is required for the hash to prove what was shown.',
   'Not auto-purged. Consent-row metadata hashes (ip_hash, device_hash) and meta_pepper_version follow consent_events retention, including the legal-claims hold on deletion.',
   'kept_no_period')
on conflict (record_type) do update
  set keep_rule = excluded.keep_rule, implemented = excluded.implemented, status = excluded.status;

-- ------------------------------------------------------------------ dedicated consent-meta pepper (dev fallback table)
-- DEV FALLBACK ONLY. Production must inject the pepper via
--   SET LOCAL app.consent_meta_pepper / app.consent_meta_pepper_version
-- from an edge secret or KMS HMAC, and must not rely on this table.
-- This is not private.encryption_keys and is not the trainer-code pepper.
create table private.consent_meta_dev_pepper (
  version          text primary key,
  pepper           text not null check (char_length(pepper) >= 32),
  is_dev_fallback  boolean not null default true check (is_dev_fallback is true),
  note             text not null default 'DEV FALLBACK ONLY. Not for production.',
  created_at       timestamptz not null default now()
);

comment on table private.consent_meta_dev_pepper is
  'DEV FALLBACK ONLY. Dedicated consent-metadata pepper; not encryption_keys and not the trainer-code pepper. Production should use an edge secret or KMS HMAC.';

alter table private.consent_meta_dev_pepper enable row level security;
alter table private.consent_meta_dev_pepper force row level security;
revoke all on table private.consent_meta_dev_pepper from public, anon, authenticated;
-- No service_role grant and no policies: the pepper is not readable through the API role.
-- Superuser (migrations / SQL tests) bypasses RLS to insert the labeled dev fixture.

create or replace function private.consent_meta_config(version out text, pepper out text, source out text)
language plpgsql
stable
security definer
set search_path = private, public, pg_temp
as $$
declare
  v_pep text := nullif(current_setting('app.consent_meta_pepper', true), '');
  v_ver text := nullif(current_setting('app.consent_meta_pepper_version', true), '');
begin
  if v_pep is not null then
    version := coalesce(nullif(btrim(v_ver), ''), 'edge');
    pepper := v_pep;
    source := 'setting';
    return;
  end if;
  select d.version, d.pepper, 'dev_fallback'
    into version, pepper, source
    from private.consent_meta_dev_pepper d
   order by d.created_at desc
   limit 1;
end;
$$;

revoke all on function private.consent_meta_config() from public, anon, authenticated;

create or replace function private.consent_meta_hmac(p_pepper text, p_domain text, p_value text)
returns text
language sql
immutable
set search_path = public, extensions, pg_temp
as $$
  select encode(
    extensions.hmac(convert_to(p_domain || ':' || p_value, 'UTF8'), convert_to(p_pepper, 'UTF8'), 'sha256'),
    'hex')
$$;

revoke all on function private.consent_meta_hmac(text, text, text) from public, anon, authenticated;

create or replace function private.consent_meta_hash(p_domain text, p_value text)
returns text
language plpgsql
stable
security definer
set search_path = private, public, extensions, pg_temp
as $$
declare
  v_cfg record;
begin
  if p_value is null or p_value = '' or p_domain is null or p_domain = '' then
    return null;
  end if;
  select * into v_cfg from private.consent_meta_config();
  if v_cfg.pepper is null then
    return null;
  end if;
  return private.consent_meta_hmac(v_cfg.pepper, p_domain, p_value);
end;
$$;

revoke all on function private.consent_meta_hash(text, text) from public, anon, authenticated;

create or replace function private.consent_meta_pepper_version()
returns text
language plpgsql
stable
security definer
set search_path = private, public, pg_temp
as $$
declare v_cfg record;
begin
  select * into v_cfg from private.consent_meta_config();
  if v_cfg.pepper is null then return null; end if;
  return v_cfg.version;
end;
$$;

revoke all on function private.consent_meta_pepper_version() from public, anon, authenticated;

-- Alert / log event: user id only. Never include an IP or request header.
create or replace function private.alert_consent_meta_pepper_missing(p_user uuid)
returns void
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
  -- Once per transaction, so a multi-row signup does not flood the audit log.
  if current_setting('app.consent_meta_alerted', true) = '1' then
    return;
  end if;
  perform set_config('app.consent_meta_alerted', '1', true);
  perform private.log_audit(
    p_user,
    'consent_meta_pepper_missing',
    p_user,
    jsonb_build_object('user_id', p_user)
  );
end;
$$;

revoke all on function private.alert_consent_meta_pepper_missing(uuid) from public, anon, authenticated;

-- ------------------------------------------------------------------ consent_events: pepper version + new hash path
alter table public.consent_events
  add column if not exists meta_pepper_version text;

create or replace function private.fill_consent_context()
returns trigger
language plpgsql
security definer
set search_path = public, private, pg_temp
as $$
declare
  v_hdr jsonb;
  v_ip text;
  v_dev text;
  v_ver text;
  v_cfg record;
begin
  begin
    v_hdr := coalesce(current_setting('request.headers', true), '')::jsonb;
  exception when others then
    v_hdr := '{}'::jsonb;
  end;
  -- Raw IP stays in a local variable and is used only as HMAC input. Never assigned
  -- to a column, raised, or written to audit metadata.
  v_ip := private.client_ip();
  v_dev := nullif(btrim(coalesce(v_hdr ->> 'x-device-id', '')), '');
  v_ver := nullif(btrim(coalesce(v_hdr ->> 'x-app-version', '')), '');
  select * into v_cfg from private.consent_meta_config();
  if v_cfg.pepper is null then
    if (new.ip_hash is null and v_ip is not null) or (new.device_hash is null and v_dev is not null) then
      perform private.alert_consent_meta_pepper_missing(new.user_id);
    end if;
  else
    begin
      if new.ip_hash is null and v_ip is not null then
        new.ip_hash := private.consent_meta_hmac(v_cfg.pepper, 'ip', v_ip);
      end if;
      if new.device_hash is null and v_dev is not null then
        new.device_hash := private.consent_meta_hmac(v_cfg.pepper, 'device', left(v_dev, 200));
      end if;
      if new.meta_pepper_version is null then
        new.meta_pepper_version := v_cfg.version;
      end if;
    exception when others then
      -- Never fail a consent write because hashing failed. Hashes stay null; alert
      -- with the user id only.
      perform private.alert_consent_meta_pepper_missing(new.user_id);
    end;
  end if;
  if new.app_version is null and v_ver is not null then
    new.app_version := left(v_ver, 32);
  end if;
  return new;
end;
$$;

drop trigger if exists consent_events_fill_context on public.consent_events;
create trigger consent_events_fill_context
  before insert on public.consent_events
  for each row execute function private.fill_consent_context();

revoke all on function private.fill_consent_context() from public, anon, authenticated;

-- request_data_export is unchanged (queue only). The TODO above is the hook for the packer.
